#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using PVZEngine;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [EntityBehaviourDefinition(VanillaProjectileNames.missile)]
    public class Missile : ProjectileExplodeBehaviour
    {
        public Missile(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Explode(Entity entity)
        {
            base.Explode(entity);
            var damage = entity.GetDamage() * 0.3f;
            Shoot(entity, VanillaProjectileID.missile_fragments_1, damage);
            Shoot(entity, VanillaProjectileID.missile_fragments_2, damage);
            for (var i = 0; i < 4; i++)
            {
                Shoot(entity, VanillaProjectileID.missile_fragments_3, damage);
            }
        }
        private void Shoot(Entity entity, NamespaceID projectileID, float damage)
        {
            var rng = entity.RNG;
            var xspeed = rng.Next(-8f, 8f);
            var zspeed = rng.Next(-8f, 8f);
            var yspeed = rng.Next(1f, 11f);
            var velocity = new Vector3(xspeed, yspeed, zspeed);

            var shootParams = entity.GetShootParams();
            shootParams.projectileID = projectileID;
            shootParams.position = entity.GetCenter();
            shootParams.pivot = VanillaEntityProps.SHOT_PIVOT_BOTTOM;
            shootParams.velocity = velocity;
            shootParams.damage = damage;
            entity.ShootProjectile(shootParams);
        }
    }
}
